const nameEl=document.getElementById('name');
const catEl=document.getElementById('cat');
const rateEl=document.getElementById('rate');
const addBtn=document.getElementById('add');
const errEl=document.getElementById('err');
const filterEl=document.getElementById('filter');
const listEl=document.getElementById('list');
const statusEl=document.getElementById('status');
let books=[];
let revs={};

function norm(s){return String(s).trim().replace(/\s+/g,' ');}

async function load(){
  try{
    const res=await tessera.call('data.read',{});
    const data=res.data||{};
    books=Array.isArray(data.books)?data.books:[];
    revs=(res.revisions&&res.revisions.books)||{};
    render();
  }catch(e){
    statusEl.textContent='Não foi possível carregar a lista. Tente abrir a ferramenta de novo.';
  }
}

function refreshFilter(){
  const current=filterEl.value;
  while(filterEl.options.length>1){filterEl.remove(1);}
  const seen=[];
  for(const b of books){
    const c=norm(b.category||'');
    if(c&&!seen.includes(c)){seen.push(c);}
  }
  seen.sort((a,b)=>a.localeCompare(b,'pt'));
  for(const c of seen){
    const o=document.createElement('option');
    o.value=c;o.textContent=c;
    filterEl.appendChild(o);
  }
  filterEl.value=seen.includes(current)?current:'';
}

function render(){
  refreshFilter();
  const f=filterEl.value;
  listEl.textContent='';
  let shown=0;
  for(const b of books){
    if(f&&norm(b.category||'')!==f){continue;}
    shown++;
    const li=document.createElement('li');
    li.setAttribute('data-hook','item');
    const info=document.createElement('div');
    info.className='info';
    const t=document.createElement('div');
    t.className='title';
    t.textContent=b.name;
    const g=document.createElement('span');
    g.className='genre';
    g.setAttribute('data-hook','category');
    g.textContent=b.category;
    const r=Number(b.rating)||0;
    const s=document.createElement('div');
    s.className='stars';
    s.textContent='Nota: '+'★'.repeat(r)+'☆'.repeat(5-r)+' ('+r+' de 5)';
    info.appendChild(t);info.appendChild(g);info.appendChild(s);
    const ctl=document.createElement('div');
    ctl.className='ctl';
    const sel=document.createElement('select');
    const sid='r-'+b.id;
    sel.id=sid;
    for(let i=1;i<=5;i++){
      const o=document.createElement('option');
      o.value=String(i);o.textContent=String(i);
      if(i===r){o.selected=true;}
      sel.appendChild(o);
    }
    const lab=document.createElement('label');
    lab.setAttribute('for',sid);
    lab.textContent='Mudar nota';
    sel.addEventListener('change',()=>changeRate(b.id,Number(sel.value)));
    const rm=document.createElement('button');
    rm.type='button';
    rm.setAttribute('data-hook','item-remove');
    rm.textContent='Remover';
    rm.setAttribute('aria-label','Remover '+b.name);
    rm.addEventListener('click',()=>removeBook(b.id));
    ctl.appendChild(lab);ctl.appendChild(sel);ctl.appendChild(rm);
    li.appendChild(info);li.appendChild(ctl);
    listEl.appendChild(li);
  }
  if(books.length===0){
    statusEl.textContent='Sua lista está vazia. Adicione o primeiro livro acima.';
  }else if(shown===0){
    statusEl.textContent='Nenhum livro nesse gênero.';
  }else{
    statusEl.textContent=shown+(shown===1?' livro':' livros')+(f?' em “'+f+'”':' na lista')+'.';
  }
}

async function addBook(){
  const name=norm(nameEl.value);
  if(!name){
    errEl.textContent='Digite o título do livro.';
    nameEl.focus();
    return;
  }
  const typed=catEl.value;
  const category=norm(typed)?typed.trim():'Sem gênero';
  errEl.textContent='';
  try{
    await tessera.call('data.patch',{operations:[{op:'add',collection:'books',record:{name:name,category:category,rating:Number(rateEl.value)}}]});
    nameEl.value='';
    await load();
    statusEl.textContent='Livro adicionado e salvo. '+statusEl.textContent;
    nameEl.focus();
  }catch(e){
    errEl.textContent='Não foi possível salvar o livro. O que você digitou foi mantido; tente de novo.';
  }
}

async function removeBook(id){
  try{
    await tessera.call('data.patch',{operations:[{op:'remove',collection:'books',id:id,revisionCount:revs[id]}]});
    await load();
  }catch(e){
    errEl.textContent='Não foi possível remover o livro. Tente de novo.';
  }
}

async function changeRate(id,value){
  try{
    await tessera.call('data.patch',{operations:[{op:'replace',collection:'books',id:id,revisionCount:revs[id],fields:{rating:value}}]});
    await load();
  }catch(e){
    errEl.textContent='Não foi possível mudar a nota. Tente de novo.';
    await load();
  }
}

addBtn.addEventListener('click',addBook);
for(const el of [nameEl,catEl]){
  el.addEventListener('keydown',(ev)=>{if(ev.key==='Enter'){ev.preventDefault();addBook();}});
}
filterEl.addEventListener('change',render);
load();
